#define main legacy_main
#include "crossEntropy-cuda/main.cu"
#undef main
#include <type_traits>
struct Case { double time=0,err=0;std::vector<double>output; };
template<class T> T cv(double x){return T(x);}template<> __half cv<__half>(double x){return __float2half(float(x));}
template<class T> double val(T x){return double(x);}template<> double val(__half x){return __half2float(x);}
template<class T> Case one(int trial){const int n=W*H;std::vector<T>p(n),g(H),gn(H),w(H),out(n);std::vector<int64_t>m(H),q(H);for(int i=0;i<n;i++)p[i]=cv<T>(-double((13*i+7)%129+1)/32);for(int i=0;i<H;i++){g[i]=cv<T>(double(i%13+1)/32);gn[i]=cv<T>(double(i%7+1)/64);w[i]=cv<T>(double(i%5+1)/8);m[i]=i%2;q[i]=(17*i+3)%W;}T *dp,*dg,*dn,*dw,*dy;int64_t*dm,*dq;cudaMalloc(&dp,n*sizeof(T));cudaMalloc(&dg,H*sizeof(T));cudaMalloc(&dn,H*sizeof(T));cudaMalloc(&dw,H*sizeof(T));cudaMalloc(&dy,n*sizeof(T));cudaMalloc(&dm,H*8);cudaMalloc(&dq,H*8);cudaMemcpy(dp,p.data(),n*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(dg,g.data(),H*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(dn,gn.data(),H*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(dw,w.data(),H*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(dm,m.data(),H*8,cudaMemcpyHostToDevice);cudaMemcpy(dq,q.data(),H*8,cudaMemcpyHostToDevice);auto run=[&](){loss_bwd<T,T><<<dim3((H+63)/64,1),64>>>(dp,dg,dn,dq,dw,dm,dy);};run();if(cudaDeviceSynchronize()!=cudaSuccess)exit(2);Case result;for(int k=0;k<10;k++){auto t=std::chrono::steady_clock::now();run();if(cudaDeviceSynchronize()!=cudaSuccess)exit(2);result.time+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;}cudaMemcpy(out.data(),dy,n*sizeof(T),cudaMemcpyDeviceToHost);result.output.resize(n);
for(int x=0;x<H;x++){T tmp=cv<T>(m[x]?-(val(g[x])+val(gn[x])):-val(g[x]));tmp=cv<T>(val(tmp)*val(w[x]));float sv=float(val(cv<T>(val(tmp)*val(p[q[x]*H+x]))));for(int c=0;c<W;c++){int off=c*H+x;double e=exp(val(p[off]));if constexpr(std::is_same_v<T,__half>)e=val(cv<T>(e));float z=float(e*sv);T expected=cv<T>(c==q[x]?float(val(tmp))-z:-z);double got=val(out[off]);if(!std::isfinite(got))result.err=INFINITY;else result.err=std::max(result.err,fabs(got-val(expected)));result.output[off]=got;}}
cudaFree(dp);cudaFree(dg);cudaFree(dn);cudaFree(dw);cudaFree(dy);cudaFree(dm);cudaFree(dq);return result;}
int main(){for(int trial=1;trial<=5;trial++){Case a=one<__half>(trial),b=one<float>(trial),c=one<double>(trial);double err=std::max(a.err,std::max(b.err,c.err));bool ok=err<=4e-3;char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");for(auto*z:{&a,&b,&c})fwrite(z->output.data(),8,z->output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.15g,\"timing_region\":\"sum_three_precision_mean_kernels\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,a.time+b.time+c.time,ok?"true":"false",3*W*H,err,path,3*W*H);if(!ok)return 1;}}
